# ---------- helpers ----------
def esc(s): return html.escape(str(s), quote=True)
def slugify(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
def write(p, content):
    p=Path(p); p.parent.mkdir(parents=True, exist_ok=True); p.write_text(content, encoding='utf-8')

def nav(active=''):
    return f'''<header class="site-header"><div class="topbar"><div class="container topbar-inner"><span>Hollywood, FL referral service</span><a href="mailto:{contact['email']}">{contact['email']}</a></div></div><div class="container nav-wrap"><a class="brand" href="/"><span class="brand-mark">H</span><span><b>Hollywood</b> Water Damage Experts<small>Independent restoration referrals</small></span></a><button class="menu-toggle" aria-label="Open navigation">☰</button><nav class="main-nav"><a href="/" class="{active=='home' and 'active' or ''}">Home</a><details><summary>Services</summary><div class="mega">{''.join(f'<a href="/services/{s[0]}/">{esc(s[1])}</a>' for s in services[:18])}</div></details><details><summary>Service Areas</summary><div class="mega">{''.join(f'<a href="/neighborhoods/{n[0]}/">{esc(n[1])}</a>' for n in neighborhoods[:16])}</div></details><details><summary>Causes</summary><div class="mega">{''.join(f'<a href="/causes/{c[0]}/">{esc(c[1])}</a>' for c in causes[:18])}</div></details><a href="/blog/">Resources</a><a href="/about/">About</a><a href="/contact/">Contact</a><a class="nav-cta" href="tel:{contact['phone']}">Call {contact['phoneDisplay']}</a></nav></div></header>'''

def footer():
    trend=[("Emergency Water Damage","/services/emergency-water-damage/"),("Water Extraction","/services/water-extraction/"),("Water Removal","/services/water-removal/"),("Flood Cleanup","/services/flood-cleanup/"),("Sewage Cleanup","/services/sewage-cleanup/"),("Mold Remediation","/services/mold-remediation/"),("Structural Drying","/services/structural-drying/"),("Water Damage Insurance","/blog/water-damage-insurance-hollywood/"),("Water Damage Cost","/blog/water-damage-cost-hollywood/"),("Water Damage FAQ","/faq/")]
    return f'''<footer><div class="container footer-grid"><div><a class="brand footer-brand" href="/"><span class="brand-mark">H</span><span><b>Hollywood</b> Water Damage Experts<small>Independent restoration referrals</small></span></a><p>Premium local referral service connecting Hollywood property owners with independent restoration professionals.</p><p><strong>Phone:</strong> <a href="tel:{contact['phone']}">{contact['phoneDisplay']}</a><br><strong>Email:</strong> <a href="mailto:{contact['email']}">{contact['email']}</a></p></div><div><h3>Services</h3>{''.join(f'<a href="/services/{s[0]}/">{esc(s[1])}</a>' for s in services[:10])}</div><div><h3>Service Areas</h3>{''.join(f'<a href="/neighborhoods/{n[0]}/">{esc(n[1])}</a>' for n in neighborhoods[:12])}</div><div><h3>Popular Resources</h3>{''.join(f'<a href="{u}">{x}</a>' for x,u in trend)}<a href="/blog/">All Restoration Guides</a></div></div><div class="container legal"><span>© 2026 {business['name']}</span><span><a href="/privacy/">Privacy</a> · <a href="/terms/">Terms</a> · <a href="/disclaimer/">Referral Disclosure</a></span></div></footer>'''

def base(title,desc,canonical,body,active='',schema=None):
    if schema is None:
        schema={"@context":"https://schema.org","@type":"WebPage","name":title,"description":desc,"url":business['domain']+canonical,"isPartOf":{"@type":"WebSite","name":business['name'],"url":business['domain']}}
    return f'''<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{business['domain']}{canonical}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="theme-color" content="#071827"><link rel="icon" href="/assets/images/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/css/styles.css"></head><body>{nav(active)}<main>{body}</main>{footer()}<script defer src="/assets/js/site.js"></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></body></html>'''

def schema_org(kind,name,url,desc=None):
    if kind=='service': return {"@context":"https://schema.org","@type":"Service","name":name,"serviceType":name,"areaServed":{"@type":"City","name":"Hollywood","addressRegion":"FL","addressCountry":"US"},"provider":{"@type":"Organization","name":business['name'],"url":business['domain']},"url":url,"description":desc or name}
    return {"@context":"https://schema.org","@type":"Organization","name":business['name'],"url":business['domain'],"email":contact['email'],"telephone":contact['phoneDisplay']}

def cta(): return f'''<div class="cta-panel"><div><span class="eyebrow">NEED HELP NOW?</span><h2>Talk through the water problem with a restoration referral specialist.</h2><p>Call <strong>{contact['phoneDisplay']}</strong> and explain what happened, where the water is, and whether it is still active.</p></div><a class="btn btn-primary" href="tel:{contact['phone']}">Call Now</a></div>'''

def faq(items): return '<section class="section faq"><div class="container"><span class="eyebrow">FAQ</span><h2>Questions people ask before calling</h2>'+''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q,a in items)+'</div></section>'

def mapbox(query): return f'''<section class="section map-section"><div class="container two-col"><div><span class="eyebrow">LOCAL COVERAGE</span><h2>Water damage help near {esc(query)}</h2><p>Use the map for local orientation. ZIP codes overlap neighborhood boundaries, so confirm the property address when you call.</p><p><strong>Area codes:</strong> 954 and 754. <strong>ZIP coverage:</strong> local Hollywood ZIPs vary by address.</p></div><iframe title="Map of {esc(query)}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://www.google.com/maps?q={esc(query)}&output=embed"></iframe></div></section>'''
