def simple_markdown(md):
    lines=md.strip().splitlines(); out=[]; para=[]
    def flush():
        nonlocal para
        if para:
            text=' '.join(para).strip(); out.append('<p>'+esc(text)+'</p>'); para=[]
    for line in lines:
        line=line.strip()
        if not line:
            flush(); continue
        if line.startswith('## '):
            flush(); out.append('<h2>'+esc(line[3:])+'</h2>')
        elif line.startswith('### '):
            flush(); out.append('<h3>'+esc(line[4:])+'</h3>')
        elif line.startswith('- '):
            flush(); out.append('<p>• '+esc(line[2:])+'</p>')
        else: para.append(line)
    flush(); return ''.join(out)

