issues=[]; titles={}; canon={}
for p in pages:
    t=p.read_text(encoding='utf-8')
    mt=re.search(r'<title>(.*?)</title>',t,re.S); mc=re.search(r'<link rel="canonical" href="([^"]+)"',t)
    h1=len(re.findall(r'<h1\b',t));
    if not mt: issues.append(f'Missing title: {p}')
    else: titles.setdefault(html.unescape(mt.group(1)),[]).append(str(p))
    if not mc: issues.append(f'Missing canonical: {p}')
    if h1!=1: issues.append(f'H1 count {h1}: {p}')
for k,v in titles.items():
    if len(v)>1: issues.append(f'Duplicate title: {k} -> {len(v)} pages')
# link existence check for local absolute hrefs
