        if href in ['/sitemap.xml','/robots.txt'] or href.startswith('/assets/'):
            continue
        if href.endswith('/'):
            target=SITE/href.strip('/')/'index.html'
        else:
            target=SITE/href.strip('/')
        if not target.exists() and (SITE/(href.strip('/')+'index.html')).exists():
            target=SITE/(href.strip('/')+'index.html')
        if not target.exists(): issues.append(f'Broken link {href} from {p.relative_to(SITE)}')
